class UserProfile {
    private int userId;
    private String username;
    private String email;
    private boolean active;

    public UserProfile(int id, String name, String email, boolean active) {
        this.userId = id;
        this.username = name;
        this.email = email;
        this.active = active;
    }

    @Override
    public String toString() {
        return "UserProfile{" +
                "userId=" + userId +
                ", username='" + username + '\'' +
                ", email='" + email + '\'' +
                ", active=" + active +
                '}';
    }
}

public class ToStringDemo {
    public static void main(String[] args) {
        UserProfile user = new UserProfile(101, "ada_lovelace", "ada@history.org", true);

        // System.out.println implicitly calls user.toString()
        System.out.println(user);
    }
}

