class PaymentAccount {
    private String accountId;
    private String rawCardNumber;
    private String cvv;

    public PaymentAccount(String accountId, String rawCardNumber, String cvv) {
        this.accountId = accountId;
        this.rawCardNumber = rawCardNumber;
        this.cvv = cvv;
    }

    private String maskCard(String card) {
        if (card.length() < 4) return "****";
        return "****-" + card.substring(card.length() - 4);
    }

    @Override
    public String toString() {
        return "PaymentAccount{" +
                "accountId='" + accountId + '\'' +
                ", card='" + maskCard(rawCardNumber) + '\'' +
                ", cvv='***'" + // Redacted completely!
                '}';
    }
}

public class SecurityToStringDemo {
    public static void main(String[] args) {
        PaymentAccount acc = new PaymentAccount("ACC-992", "4111222233334567", "123");
        System.out.println(acc);
    }
}

