class SecureUser {
    private String username;
    private String email;
    private String passwordHash;
    private String ssn;

    public SecureUser(String username, String email, String passwordHash, String ssn) {
        this.username = username;
        this.email = email;
        this.passwordHash = passwordHash;
        this.ssn = ssn;
    }

    @Override
    public String toString() {
        String maskedSsn = "***-**-" + ssn.substring(ssn.length() - 4);
        return "SecureUser{username=\"" + username + "\", email=\"" + email + "\", ssn=\"" + maskedSsn + "\", pass=\"[REDACTED]\"}";
    }
}

public class SecureApp {
    public static void main(String[] args) {
        SecureUser user = new SecureUser("alice_w", "alice@cyber.gov", "e99a18c428cb38d5", "123-45-6789");
        System.out.println(user);
    }
}

import java.util.ArrayList;
import java.util.List;

class LineItem {
    private String itemSku;
    private int qty;
    public LineItem(String itemSku, int qty) {
        this.itemSku = itemSku;
        this.qty = qty;
    }
    @Override
    public String toString() {
        return "LineItem(sku=" + itemSku + ", qty=" + qty + ")";
    }
}

class PurchaseOrder {
    private String orderNum;
    private List<LineItem> items = new ArrayList<>();
    public PurchaseOrder(String orderNum) {
        this.orderNum = orderNum;
    }
    public void addItem(String sku, int qty) {
        items.add(new LineItem(sku, qty));
    }
    @Override
    public String toString() {
        return "PurchaseOrder[num=" + orderNum + ", items=" + items + "]";
    }
}

public class PurchaseApp {
    public static void main(String[] args) {
        PurchaseOrder order = new PurchaseOrder("PO-770");
        order.addItem("WIDGET-A", 2);
        order.addItem("BOLT-B", 5);
        System.out.println(order);
    }
}

