class TelemetryPacket {
    private String deviceId;
    private double temperatureC;
    private double batteryVolts;
    private boolean alertActive;

    public TelemetryPacket(String deviceId, double temp, double volts, boolean alert) {
        this.deviceId = deviceId;
        this.temperatureC = temp;
        this.batteryVolts = volts;
        this.alertActive = alert;
    }

    @Override
    public String toString() {
        return "TelemetryPacket[id=\"" + deviceId + "\", temp=" + temperatureC + "C, batt=" + batteryVolts + "V, alert=" + alertActive + "]";
    }

    public String toJson() {
        return "{\"deviceId\": \"" + deviceId + "\", \"temperature\": " + temperatureC + ", \"battery\": " + batteryVolts + ", \"alert\": " + alertActive + "}";
    }
}

public class TelemetryApp {
    public static void main(String[] args) {
        TelemetryPacket packet = new TelemetryPacket("SAT-09", -15.4, 3.82, false);
        System.out.println(packet);
        System.out.println(packet.toJson());
    }
}
